def dash_steps(total_length, dash_length, gap_length):
    if total_length < 0:
        raise ValueError("total_length must not be negative")
    if dash_length <= 0:
        raise ValueError("dash_length must be positive")
    if gap_length < 0:
        raise ValueError("gap_length must not be negative")
    steps = []
    remaining = total_length
    while remaining > 0:
        dash = min(dash_length, remaining)
        steps.append([dash, True])
        remaining -= dash
        if remaining <= 0:
            break
        gap = min(gap_length, remaining)
        if gap > 0:
            steps.append([gap, False])
            remaining -= gap
    return steps

