import numpy as np


def one_hot(labels, num_classes):
    if num_classes < 1:
        raise ValueError("num_classes must be at least 1")
    labels = list(labels)
    for label in labels:
        if not 0 <= label < num_classes:
            raise ValueError("label out of range")
    out = np.zeros((len(labels), num_classes), dtype=int)
    for row, label in enumerate(labels):
        out[row, label] = 1
    return out

import io
import pandas as pd


def monthly_totals(csv_text):
    frame = pd.read_csv(io.StringIO(csv_text))
    if frame.empty:
        return ([], [])
    months = pd.to_datetime(frame["date"]).dt.strftime("%Y-%m")
    grouped = frame.assign(month=months).groupby("month")["amount"].sum().sort_index()
    return (list(grouped.index), [float(value) for value in grouped.tolist()])

