def scale_boxes(boxes, factor):
    if factor <= 0:
        raise ValueError("factor must be greater than 0")
    return [
        (x1 * factor, y1 * factor, x2 * factor, y2 * factor)
        for x1, y1, x2, y2 in boxes
    ]

