import math


def pick_best_match(encodings, target, threshold):
    if not encodings:
        return None
    best_index = None
    best_distance = None
    for index, candidate in enumerate(encodings):
        if len(candidate) != len(target):
            raise ValueError("encoding length mismatch")
        distance = math.sqrt(sum((a - b) ** 2 for a, b in zip(candidate, target)))
        if best_distance is None or distance < best_distance:
            best_distance = distance
            best_index = index
    if best_distance <= threshold:
        return best_index
    return None
